CREATE OR REPLACE FUNCTION public.workflow_inbox_account_visible(p_workspace uuid,p_channel text,p_account uuid) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public,pg_temp AS $$ DECLARE c jsonb:=public.work_access_context();k jsonb:=c->'keys';BEGIN IF auth.uid() IS NULL OR auth.role() IS DISTINCT FROM 'authenticated' OR c->>'workspace' IS DISTINCT FROM p_workspace::text OR c->>'actor' IS DISTINCT FROM auth.uid()::text OR NOT public.is_workspace_member(p_workspace,auth.uid()) THEN RETURN false;END IF;IF p_channel='email' THEN RETURN coalesce(k ?| ARRAY['techsales.inbox.email.view.own','techsales.inbox.email.view.team','techsales.inbox.email.view.workspace'],false) AND EXISTS(SELECT 1 FROM public.email_accounts WHERE id=p_account AND workspace_id=p_workspace AND provider='gmail' AND status='connected');END IF;IF p_channel='chat' THEN RETURN p_account=p_workspace AND coalesce(k ?| ARRAY['techsales.inbox.chat.view.own','techsales.inbox.chat.view.team','techsales.inbox.chat.view.workspace'],false);END IF;IF p_channel='linkedin' THEN RETURN coalesce((k->>'techsales.inbox.linkedin.view.own')::boolean,false) AND EXISTS(SELECT 1 FROM public.unipile_accounts WHERE id=p_account AND workspace_id=p_workspace AND owner_id=auth.uid() AND status='connected');END IF;RETURN false;END $$;
ALTER FUNCTION techerp_api.notification_source_visible(uuid,uuid,text,uuid) RENAME TO notification_source_visible_before_inbox_channels;
CREATE FUNCTION techerp_api.notification_source_visible(p_ws uuid,p_user uuid,p_table text,p_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF p_table='inbox_channel_occurrences' THEN RETURN techerp_api.inbox_subject_visible(p_ws,p_user,p_id);END IF;RETURN techerp_api.notification_source_visible_before_inbox_channels(p_ws,p_user,p_table,p_id);END $$;
ALTER FUNCTION techerp_api.notification_source_visible(uuid,uuid,text,uuid) OWNER TO techerp_api_subject;
REVOKE ALL ON FUNCTION techerp_api.notification_source_visible(uuid,uuid,text,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION techerp_api.notification_source_visible(uuid,uuid,text,uuid) TO postgres;
ALTER FUNCTION techerp_api.notification_center_source_visible(uuid,uuid,text,uuid) RENAME TO notification_center_source_visible_before_inbox_channels;
CREATE FUNCTION techerp_api.notification_center_source_visible(p_ws uuid,p_user uuid,p_table text,p_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF p_table='inbox_channel_occurrences' THEN IF auth.uid() IS DISTINCT FROM p_user OR auth.role() IS DISTINCT FROM 'authenticated' OR public.work_access_context()->>'workspace' IS DISTINCT FROM p_ws::text THEN RETURN false;END IF;RETURN techerp_api.inbox_subject_visible(p_ws,p_user,p_id);END IF;RETURN techerp_api.notification_center_source_visible_before_inbox_channels(p_ws,p_user,p_table,p_id);END $$;
REVOKE ALL ON FUNCTION techerp_api.notification_center_source_visible(uuid,uuid,text,uuid) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION techerp_api.notification_center_source_visible(uuid,uuid,text,uuid) TO postgres;
CREATE OR REPLACE FUNCTION techerp_api.notification_business_module(p_key text,p_workspace uuid,p_user uuid,p_table text,p_id uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN IF techerp_api.notification_business_category(p_key) IS NOT NULL THEN IF NOT techerp_api.notification_center_source_visible(p_workspace,p_user,p_table,p_id) THEN RETURN NULL;END IF;RETURN CASE WHEN p_key='shared.message.received' OR techerp_api.inbox_event_channel(p_key) IS NOT NULL THEN 'crm' ELSE split_part(p_key,'.',1) END;END IF;RETURN techerp_api.notification_center_source_module(p_workspace,p_user,p_table,p_id);END $$;
ALTER FUNCTION public.notification_business_event_check(uuid,uuid,integer) RENAME TO notification_business_event_check_before_inbox_channels;
CREATE FUNCTION public.notification_business_event_check(p_event uuid,p_workflow uuid,p_version integer) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE e record;p record;r record;root record;f record;o record;x record;a record;s jsonb;executor uuid;BEGIN PERFORM techerp_api.notification_service();SELECT * INTO e FROM public.workflow_events WHERE id=p_event;IF NOT FOUND THEN RETURN false;END IF;IF techerp_api.inbox_event_channel(e.notification_event_key) IS NULL THEN RETURN public.notification_business_event_check_before_inbox_channels(p_event,p_workflow,p_version);END IF;
 SELECT * INTO p FROM public.notification_business_event_proofs WHERE event_id=e.id;IF NOT FOUND THEN RETURN false;END IF;SELECT * INTO r FROM public.notification_business_event_proofs WHERE event_id=p.root_event_id;IF NOT FOUND THEN RETURN false;END IF;SELECT * INTO root FROM public.workflow_events WHERE id=r.event_id;IF NOT FOUND THEN RETURN false;END IF;SELECT * INTO o FROM public.inbox_channel_occurrences WHERE id=r.source_id;IF NOT FOUND THEN RETURN false;END IF;SELECT * INTO x FROM public.inbox_channel_evidence WHERE id=o.envelope_id;IF NOT FOUND THEN RETURN false;END IF;SELECT * INTO f FROM public.workflows WHERE id=p_workflow AND workspace_id=e.workspace_id AND entity='inbox_channel_occurrences' AND enabled AND status='published' AND published_version=p_version;IF NOT FOUND THEN RETURN false;END IF;SELECT * INTO a FROM public.inbox_workflow_activations WHERE workflow_id=f.id AND workspace_id=f.workspace_id AND workflow_version=p_version;IF NOT FOUND THEN RETURN false;END IF;s:=techerp_api.inbox_snapshot(o.id);
 IF e.entity<>'inbox_channel_occurrences' OR e.notification_event_key IS DISTINCT FROM f.trigger#>>'{notification_event,key}' OR o.event_key IS DISTINCT FROM e.notification_event_key OR o.workspace_id IS DISTINCT FROM e.workspace_id OR p.payload_hash IS DISTINCT FROM techerp_api.notification_business_event_hash(jsonb_populate_record(NULL::public.workflow_events,to_jsonb(e))) OR r.payload_hash IS DISTINCT FROM techerp_api.notification_business_event_hash(jsonb_populate_record(NULL::public.workflow_events,to_jsonb(root))) OR r.root_event_id IS DISTINCT FROM r.event_id OR r.parent_event_id IS NOT NULL OR root.notification_parent_event_id IS NOT NULL OR ROW(p.workspace_id,p.event_key,p.source_table,p.source_id,p.producer_table,p.producer_id,p.reference_id,p.source_revision) IS DISTINCT FROM ROW(r.workspace_id,r.event_key,r.source_table,r.source_id,r.producer_table,r.producer_id,r.reference_id,r.source_revision) OR r.source_table<>'inbox_channel_occurrences' OR r.producer_table<>'inbox_channel_evidence' OR r.producer_id IS DISTINCT FROM x.id OR r.reference_id IS DISTINCT FROM o.conversation_id OR r.source_revision IS DISTINCT FROM encode(sha256(convert_to(s::text,'UTF8')),'hex') OR x.workspace_id IS DISTINCT FROM o.workspace_id OR x.channel IS DISTINCT FROM o.channel OR x.account_id IS DISTINCT FROM o.account_id OR x.conversation_id IS DISTINCT FROM o.conversation_id OR o.received_at<a.activated_at OR o.occurred_at<a.activated_at OR (p.workflow_id IS NOT NULL AND (p.workflow_id IS DISTINCT FROM f.id OR p.workflow_version IS DISTINCT FROM p_version)) OR (e.workflow_version IS NOT NULL AND e.workflow_version IS DISTINCT FROM p_version) OR (e.resume_workflow_id IS NOT NULL AND e.resume_workflow_id IS DISTINCT FROM f.id) OR NOT techerp_api.inbox_account_current(o.workspace_id,o.channel,o.account_id) OR f.trigger?'time_based' OR NOT techerp_api.inbox_actions_valid(f.actions) OR (coalesce(f.trigger#>'{notification_event,account_ids}','[]')<>'[]' AND NOT(f.trigger#>'{notification_event,account_ids}' ? o.account_id::text)) THEN RETURN false;END IF;
 executor:=coalesce(f.execution_user_id,f.owner_id);RETURN techerp_api.inbox_subject_visible(o.workspace_id,executor,o.id) AND public.sales_worker_authorize('workflows',f.id,jsonb_build_array(jsonb_build_object('workflow_version',p_version),jsonb_build_object('record_table','inbox_channel_occurrences','id',o.id,'action','view')));END $$;
REVOKE ALL ON FUNCTION public.notification_business_event_check(uuid,uuid,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.notification_business_event_check(uuid,uuid,integer) TO service_role;
ALTER FUNCTION techerp_api.sales_worker_check(text,uuid,uuid,uuid,jsonb) RENAME TO sales_worker_check_before_inbox_channels;
CREATE FUNCTION techerp_api.sales_worker_check(p_source text,p_id uuid,p_user uuid,p_ws uuid,p_refs jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE ref jsonb;remaining jsonb:='[]';BEGIN IF jsonb_typeof(p_refs) IS DISTINCT FROM 'array' THEN RETURN false;END IF;FOR ref IN SELECT * FROM jsonb_array_elements(p_refs) LOOP IF coalesce(ref->>'record_table',ref->>'table')='inbox_channel_occurrences' THEN IF coalesce(ref->>'action','view')<>'view' OR NOT techerp_api.inbox_subject_visible(p_ws,p_user,(ref->>'id')::uuid) THEN RETURN false;END IF;ELSE remaining:=remaining||jsonb_build_array(ref);END IF;END LOOP;RETURN techerp_api.sales_worker_check_before_inbox_channels(p_source,p_id,p_user,p_ws,remaining);END $$;
REVOKE ALL ON FUNCTION techerp_api.sales_worker_check(text,uuid,uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;
GRANT EXECUTE ON FUNCTION techerp_api.sales_worker_check(text,uuid,uuid,uuid,jsonb) TO postgres;
CREATE FUNCTION techerp_api.inbox_event_snapshot_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE expected jsonb;BEGIN IF NEW.entity<>'inbox_channel_occurrences' THEN RETURN NEW;END IF;expected:=techerp_api.inbox_snapshot(NEW.entity_id);IF techerp_api.inbox_event_channel(NEW.notification_event_key) IS NULL OR expected IS NULL OR expected->>'workspace_id' IS DISTINCT FROM NEW.workspace_id::text OR expected->>'event_key' IS DISTINCT FROM NEW.notification_event_key THEN RAISE EXCEPTION 'Ocorrência inválida.' USING ERRCODE='42501';END IF;IF NEW.notification_parent_event_id IS NULL AND NEW.after IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Metadados inválidos.' USING ERRCODE='42501';END IF;RETURN NEW;END $$;
REVOKE ALL ON FUNCTION techerp_api.inbox_event_snapshot_guard() FROM PUBLIC,anon,authenticated,service_role;
CREATE TRIGGER inbox_event_snapshot_guard BEFORE INSERT ON public.workflow_events FOR EACH ROW EXECUTE FUNCTION techerp_api.inbox_event_snapshot_guard();
NOTIFY pgrst,'reload schema';
